import sys
lines = sys.stdin.read().splitlines()
out = []
trie = {}
if lines:
    m = int(lines[0])
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        op, w = cmd[0], cmd[1]
        if op == 'INSERT':
            node = trie
            for c in w: node = node.setdefault(c, {})
            node['#'] = True
        elif op == 'SEARCH':
            node = trie
            ok = True
            for c in w:
                if c not in node: ok = False; break
                node = node[c]
            out.append('true' if ok and '#' in node else 'false')
        elif op == 'STARTSWITH':
            node = trie
            ok = True
            for c in w:
                if c not in node: ok = False; break
                node = node[c]
            out.append('true' if ok else 'false')
print(' '.join(out))
